@router.post('/{session_id}/fork')
async def fork_session(session_id: str, req: SessionForkRequest = None):
    """从某条消息分叉新会话。"""
    db = _db()
    if not db:
        return {'error': 'Agent 未初始化'}

    new_id = str(uuid.uuid4())[:8]
    title = (req.title if req and req.title else '') or '分叉会话'

    # 使用 SessionFork 从事件日志分叉
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    source_log = app._get_session_log(session_id)

    if req and req.message_id:
        # 从指定消息分叉：找到对应的 session_events seq
        events = source_log.get_events(limit=100000)
        boundary_seq = None
        user_msg_count = 0
        for ev in events:
            if ev.type == 'user_message':
                user_msg_count += 1
                if user_msg_count >= req.message_id:
                    boundary_seq = ev.seq
                    break
        if boundary_seq is not None:
            new_log = source_log.fork(boundary_seq=boundary_seq,
                                      new_session_id=new_id)
        else:
            # fallback: 复制全部事件
            new_log = source_log.fork(boundary_seq=999999,
                                      new_session_id=new_id)
    else:
        # 无指定消息：创建空会话
        pass

    # 创建 session 记录
    session = db.create_session(new_id, title)
    return session
